// export precisa bater com o 'export' declarado no target, em shopify.extension.toml
export function cartLinesDiscountsGenerateRun(input) {
  const totalQty = input.cart.lines.reduce((sum, l) => sum + l.quantity, 0);
  if (totalQty < 3) return { operations: [] };

  return {
    operations: [{
      orderDiscountsAdd: {
        selectionStrategy: "FIRST",
        candidates: [{
          message: "10% OFF acima de 3 itens",
          targets: [{ orderSubtotal: { excludedCartLineIds: [] } }],
          value: { percentage: { value: "10.0" } }
        }]
      }
    }]
  };
}
